import { defineAgent } from 'eve';
import { SupportOutputSchema } from './contracts.js';
const MODEL = 'provider/model';
export default defineAgent({ description: 'Supports customers.', model: MODEL, outputSchema: SupportOutputSchema });

export const SupportOutputSchema = {};
export const SearchInputSchema = {};
export const SearchOutputSchema = {};

import { defineInstructions } from 'eve/instructions';
import { loadInstruction } from './loaders.js';
export default defineInstructions({ content: loadInstruction(), role: 'system' });

import { defineTool } from 'eve/tools';
import { SearchInputSchema, SearchOutputSchema } from '../contracts.js';
import { searchKnowledge } from '../implementations.js';
export default defineTool({ description: 'Searches the knowledge base.', inputSchema: SearchInputSchema, outputSchema: SearchOutputSchema, execute: searchKnowledge });
